(function(){"use strict";function S(t,s,n){const e=Math.floor(n/12),a=n%12,r=t*(.34+e*.16),i=s*(.32+e*.16),o=Math.PI*2*a/12-Math.PI/2;return{x:t/2+r*Math.cos(o),y:s/2+i*Math.sin(o)}}function I(t,s,n){const e=Math.floor(n/16),a=n%16,r=56+e*30,i=Math.PI*2*a/16-Math.PI/2;return{x:t+r*Math.cos(i),y:s+r*Math.sin(i)}}function O(t,s=720,n=360){const e=t.boundaries.map((o,c)=>({networkId:o.network_id,slot:c,...S(s,n,c)})),a=new Map(e.map(o=>[o.networkId,o])),r=new Map,i=[];for(const o of t.nodes){const c=o.networks.map(_=>a.get(_.network_id)).find(_=>_!==void 0);if(!c)continue;const d=r.get(c.networkId)??0;r.set(c.networkId,d+1),i.push({nodeId:o.node_id,anchorNetworkId:c.networkId,slot:d,...I(c.x,c.y,d)})}return{width:s,height:n,anchors:e,placements:i}}const u=globalThis;u.onmessage=t=>{const{requestId:s,snapshot:n,width:e,height:a}=t.data;u.postMessage({requestId:s,layout:O(n,e,a)})}})();
